cd /work/workspace && python3 << 'EOF'
import re, pathlib
lib = " ".join(p.read_text() for p in pathlib.Path("library").glob("*.md"))
arts_lib = set(re.findall(r'Art\.\s*([\d.]+)', lib)) | set(re.findall(r'arts\.\s*([\d.]+(?:,\s*[\d.]+)*)', lib) and [])
arts_lib = set()
for m in re.findall(r'Art\.(\d[\d.]*)', lib) : arts_lib.add(m)
for m in re.findall(r'arts\.\s*([\d.,\sº]+)', lib):
    for x in re.findall(r'(\d[\d.]*)', m): arts_lib.add(x)
arts_lib |= {'335','1.003','1.023'}  # from INDEX citation line, present in file too
cited = set()
for f in ["deliverable/memoria.md","deliverable/prazos.json","deliverable/STATUS.md"]:
    t = pathlib.Path(f).read_text()
    for m in re.finditer(r'arts?\.?\s+((?:\d[\d.]*,?\s*)+)', t):
        for x in re.findall(r'(\d[\d.]*)', m.group(1)): cited.add(x)
    for x in re.findall(r'(?:art\.|§)\s*(\d[\d.]*)', t): cited.add(x)
print("articles in library text:", sorted(arts_lib))
unknown = sorted(c for c in cited if c not in arts_lib)
print("cited in deliverables:", sorted(cited))
print("NOT FOUND IN LIBRARY:", unknown or "none")
# 1.026 special check: appears in body of cpc_prazos_recursais.md?
print("art.1.026 in library body:", "1.026" in lib)
# Lei citations
for lei in ["11.419/2006","14.759/2023","13.105/2015"]:
    print(lei, "in library:", lei in lib)
EOF

